# Load all demo pairs and test input
import os, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    demo_re = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
    for m in demo_re.finditer(t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end() :].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Keys:", sorted(G.keys()))
for key in sorted(G.keys()):
    print(f"\n=== {key} ({len(G[key][0])}x{len(G[key])}) ===")
    for row in G[key]:
        print(' '.join(str(c) for c in row))
